        protected DataClassesDatabaseDataContext db = new DataClassesDatabaseDataContext();

        [HttpGet]
        public virtual IHttpActionResult List(int page = 1, int pageSize = 20)
        {
            if (page < 1) page = 1;
            if (pageSize < 1) pageSize = 20;
            if (pageSize > 100) pageSize = 100;

            var query = GetQuery();
            var total = query.Count();
            var items = query.Skip((page - 1) * pageSize).Take(pageSize).ToList()
                             .Select(MapToViewModel).ToList();

            return Ok(new {
                Total = total,
                Page = page,
                PageSize = pageSize,
                TotalPages = (int)Math.Ceiling((double)total / pageSize),
                Data = items
            });
        }

