            if (entity == null) return NotFound();
            return Ok(MapToViewModel(entity));
        }

        [HttpPost]
        public virtual IHttpActionResult Create(TViewModel model)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);
            var entity = MapToEntity(model);
            InsertEntity(entity);
            db.SubmitChanges();
            return Ok(MapToViewModel(entity));
        }

        [HttpPut]
        public virtual IHttpActionResult Update(TKey id, TViewModel model)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);
            var entity = FindEntity(id);
            if (entity == null) return NotFound();
            UpdateEntity(entity, model);
            db.SubmitChanges();
            return Ok(MapToViewModel(entity));
        }

        [HttpDelete]
